def numOfWays(points):
    n = len(points)
    count = 0

    for i in range(n):
        x1, y1 = points[i]
        for j in range(n):
            if i == j:
                continue
            x2, y2 = points[j]
            # Alice: upper-left, Bob: lower-right
            if x1 < x2 and y1 < y2:
                found_inside = False
                # Check if any other point lies inside/on the fence
                for k in range(n):
                    if k == i or k == j:
                        continue
                    x, y = points[k]
                    if x1 <= x <= x2 and y1 <= y <= y2:
                        found_inside = True
                        break
                if not found_inside:
                    count += 1
    return count
